import {createChatOrchestrator} from './chatOrchestrator.js';
import {ToolRegistry} from './tools/registry.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider, MessageChunk, UsageMetadata} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

export async function reportedUsage(sendMessage: () => AsyncGenerator<MessageChunk>): Promise<UsageMetadata | undefined> {
  const provider: AIProvider = {
    sendMessage,
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
  const registry = new ToolRegistry();
  registry.register({name: 'lookup', description: 'Lookup', inputSchema: {type: 'object'}}, async () => 'found');
  let total: UsageMetadata | undefined;
  const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'Test'}), registry, {
    hooks: {afterModelResponse: async (_session, _text, usage) => { total = usage; }},
  });
  const session: ChatSession = {
    sessionId: 's',
    userId: 'u',
    entries: [{role: 'user', content: 'Hi', timestamp: '2026-01-01T00:00:00.000Z'}],
  };
  await orchestrator.processMessage(session);
  return total;
}
EOF
cat > src/orchestration/chatOrchestratorUsage.test.ts <<'EOF'
import {reportedUsage} from './usageTestFixture.js';
import type {MessageChunk} from '../types/ai.js';

it('adds usage from two provider calls (specs/hal-engine-config-hooks/spec.md#10)', async () => {
  let round = 0;
  const total = await reportedUsage(async function* (): AsyncGenerator<MessageChunk> {
    if (round++ === 0) {
      yield {type: 'tool_use', toolCall: {id: '1', name: 'lookup', input: {}}};
      yield {type: 'stop', stopReason: 'tool_use', usage: {inputTokens: 2, outputTokens: 3, totalTokens: 5}};
      return;
    }
    yield {type: 'stop', stopReason: 'end_turn', usage: {inputTokens: 7, outputTokens: 11, totalTokens: 18}};
  });
  expect(total).toEqual({inputTokens: 9, outputTokens: 14, totalTokens: 23});
});
EOF
